// The Worker's entry point (wrangler.jsonc "main"): the OpenNext build of the
// app (.open-next/worker.js, written by `opennextjs-cloudflare build`), wrapped
// by Sentry (./sentry.ts), plus the end-of-day run: the Cron Trigger's
// scheduled() handler and its Workflow (./night.ts), and the weekly model
// watch (./model-watch.ts).
import * as Sentry from "@sentry/cloudflare";
// Generated by the build, so missing before one (ts-expect-error would then
// fail after one).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNext from "../.open-next/worker.js";
import { sentryOptions } from "./sentry";
import { serveImage } from "./assets";
import { PEOPLE_QUEUE_CRON, drainPeople, startTonight, type NightEnv } from "./night";
import { MODEL_WATCH_CRON, watchModels } from "./model-watch";

// The end-of-day Workflow (wrangler.jsonc workflows, binding NIGHT).
export { EndOfDayWorkflow } from "./night";

// The ISR revalidation queue's Durable Object (wrangler.jsonc durable_objects).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
export { DOQueueHandler } from "../.open-next/worker.js";

type Handler = {
  fetch: (request: Request, env: CloudflareEnv, ctx: { waitUntil(promise: Promise<unknown>): void }) => Promise<Response>;
};
const app = openNext as Handler;

// Screenshots and favicons skip the Next.js app (./assets.ts); the rest is the app.
const worker = {
  ...app,
  async fetch(request: Request, env: CloudflareEnv, ctx: { waitUntil(promise: Promise<unknown>): void }) {
    return (await serveImage(request, env, ctx)) ?? app.fetch(request, env, ctx);
  },
  // Cron Triggers (wrangler.jsonc triggers.crons): 03:30 and 04:30 UTC, one
  // of which is 20:30 in Los Angeles, start tonight's run; the hourly one
  // finishes people's grade requests that waited for Gemini 3.5; the weekly
  // one is model watch (./model-watch.ts).
  async scheduled(controller: { scheduledTime: number; cron: string }, env: CloudflareEnv) {
    if (controller.cron === PEOPLE_QUEUE_CRON) await drainPeople(env as NightEnv);
    else if (controller.cron === MODEL_WATCH_CRON) await watchModels(env as NightEnv, new Date(controller.scheduledTime));
    else await startTonight(controller.scheduledTime, env as NightEnv);
  },
};

export default Sentry.withSentry((env: CloudflareEnv) => sentryOptions(env), worker as Parameters<typeof Sentry.withSentry>[1]);
